"""round and trunc of a numeric to a said scale on ClickHouse (REQ-2236; REQ-2171): a scale below
zero (ClickHouse's round takes -38 and up; below it every numeric a Decimal holds is 0), a scale
the statement writes as an integer's text ('0'::integer), and -2147483648::integer, whose cast
raises 22003 before the negation. Each answered on the embedded engine (chdb) against the embedded
PostgreSQL 16.11's answer. A scale past 18 and a numeric past 38 digits stay refused by name."""

# Requirements: REQ-2236, REQ-2171

from __future__ import annotations

from decimal import Decimal

import pytest

from provisa.core.pg_error import PostgresError, from_engine
from provisa.federation.clickhouse_runtime import ClickHouseFederationRuntime
from provisa.transpiler.function_macros import FunctionRefused, RowRefused
from provisa.transpiler.transpile import transpile

