@pytest.fixture(scope="module")
def runtime() -> ClickHouseFederationRuntime:
    return ClickHouseFederationRuntime.embedded()


def _answer(runtime: ClickHouseFederationRuntime, sql: str) -> object:
    ((value,),) = list(runtime.run_sync(transpile(sql, "clickhouse")).iter_rows())
    return value


def _same(want: str | None, got: object) -> bool:
    """A numeric's text against the engine's Decimal: its value and its scale."""
    if want is None or got is None:
        return want is got
    expected = Decimal(want)
    value = Decimal(str(got))
    return value == expected and value.as_tuple().exponent == expected.as_tuple().exponent


#: A scale past ClickHouse's 18 places, or a numeric past a Decimal's 38 digits: refused by name.
_PAST_THE_BOUND = ("1000::numeric, 42", "2147483647", "123456789012345678901234567890.1234")


@pytest.mark.parametrize(
    ("sql", "want"),
    [(s, w) for s, w in ANSWERED if not any(p in s for p in _PAST_THE_BOUND)],
)
def test_clickhouse_answers_postgresql_s(runtime, sql, want):
    got = _answer(runtime, sql)
    assert _same(want, got), (want, got)


@pytest.mark.parametrize(("sql", "state"), RAISED)
def test_clickhouse_raises_postgresql_s_error(runtime, sql, state):
    with pytest.raises(Exception) as raised:
        _answer(runtime, sql)
    if isinstance(raised.value, (RowRefused, PostgresError)):
        assert raised.value.sqlstate == state
        return
    error = from_engine(raised.value)
    assert error is not None and error.sqlstate == state, str(raised.value)[:300]


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT round(1000::numeric, 42::integer)",
        "SELECT trunc(2.5::numeric, '2147483647'::integer)",
    ],
)
def test_a_scale_past_18_is_refused_by_name(sql):
    with pytest.raises(FunctionRefused):
        transpile(sql, "clickhouse")


def test_trino_still_refuses_a_negative_scale():
    with pytest.raises(FunctionRefused):
        transpile("SELECT round(2.5::numeric, (-2)::integer)", "trino")
